script:
(function () {
  'use strict';
  // Educational risk-tolerance questionnaire, broad portfolio. Not investment advice.
  //   Eight questions, each answer worth 1 to 4 points; score = sum, 8 to 32.
  //   Score bands: 8-12, 13-17, 18-22, 23-27, 28-32 map to five illustrative profiles.
  //   Each profile has a fixed hypothetical mix across eight asset classes (every mix totals 100%).
  // Checked in Node (aq5/tests/q.test.js): every mix totals 100%; scores 8, 12, 13, 17, 18, 22, 23,
  // 27, 28 and 32 land in the right band; all-lowest answers give the most conservative profile and
  // all-highest the growth profile; fewer than eight answers shows no profile.
  var QUESTIONS = 8;
  var CLASSES = ['US large-cap stocks', 'US small and mid-cap stocks', 'International developed stocks',
                 'Emerging-market stocks', 'Real estate', 'US investment-grade bonds',
                 'Inflation-protected bonds', 'Short-term bonds and cash'];
  var GROUP = ['Stocks', 'Stocks', 'Stocks', 'Stocks', 'Real estate', 'Bonds', 'Bonds', 'Cash and short-term'];
  var PROFILES = [
    { min: 8, max: 12, name: 'Conservative', mix: [10, 3, 5, 0, 2, 45, 15, 20],
      text: 'Answers in this range point to a short time frame, a need for income or stability, or discomfort with losses. The illustrative mix leans heavily on bonds and cash.' },
    { min: 13, max: 17, name: 'Moderately conservative', mix: [18, 5, 9, 2, 4, 40, 10, 12],
      text: 'Answers in this range accept some ups and downs in exchange for modest growth, while keeping most of the illustrative mix in bonds and cash.' },
    { min: 18, max: 22, name: 'Moderate', mix: [27, 7, 13, 3, 5, 32, 6, 7],
      text: 'Answers in this range balance growth and stability. The illustrative mix holds about half in stocks and real estate and half in bonds and cash.' },
    { min: 23, max: 27, name: 'Moderate growth', mix: [34, 10, 17, 5, 6, 20, 4, 4],
      text: 'Answers in this range point to a longer time frame and tolerance for sizeable swings. The illustrative mix is mostly stocks and real estate.' },
    { min: 28, max: 32, name: 'Growth', mix: [41, 12, 21, 8, 6, 8, 2, 2],
      text: 'Answers in this range point to a long time frame, little need for income from this money and comfort with deep temporary losses. The illustrative mix is almost all stocks and real estate.' }
  ];

  // --- calc start
  function profileFor(score) {
    for (var i = 0; i < PROFILES.length; i++) {
      if (score >= PROFILES[i].min && score <= PROFILES[i].max) return i;
    }
    return -1;
  }
  function rollUp(mix) {
    var out = {};
    mix.forEach(function (p, i) { out[GROUP[i]] = (out[GROUP[i]] || 0) + p; });
    return out;
  }
  // --- calc end

  function set(id, text) { document.getElementById(id).textContent = text; }

  function answers() {
    var vals = [];
    for (var q = 1; q <= QUESTIONS; q++) {
      var r = document.querySelector('input[name="qbQ' + q + '"]:checked');
      vals.push(r ? parseInt(r.value, 10) : null);
    }
    return vals;
  }

  function cell(text, strong) {
    var td = document.createElement(strong ? 'th' : 'td');
    if (strong) td.setAttribute('scope', 'row');
    td.textContent = text;
    return td;
  }

  function renderCompare(active) {
    var body = document.getElementById('qbCompare');
    body.textContent = '';
    CLASSES.forEach(function (name, i) {
      var tr = document.createElement('tr');
      tr.appendChild(cell(name, true));
      PROFILES.forEach(function (p, k) {
        var td = cell(p.mix[i] + '%');
        if (k === active) td.className = 'font-semibold text-ink';
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
    PROFILES.forEach(function (p, k) {
      var th = document.getElementById('qbHead' + k);
      th.textContent = p.name + (k === active ? ' (your score)' : '');
    });
  }

  function update() {
    var vals = answers(), done = vals.filter(function (v) { return v !== null; }).length;
    var score = vals.reduce(function (a, v) { return a + (v || 0); }, 0);
    set('qbProgress', done + ' of ' + QUESTIONS + ' questions answered');
    var mixBody = document.getElementById('qbMix');
    mixBody.textContent = '';
    if (done < QUESTIONS) {
      set('qbScore', done ? score + ' so far' : '–');
      set('qbProfile', 'Answer every question');
      set('qbProfileText', 'The score and the matching illustrative mix appear once all ' + QUESTIONS + ' questions are answered.');
      ['qbStocks', 'qbBonds', 'qbRealEstate', 'qbCashShare'].forEach(function (id) { set(id, '–'); });
      renderCompare(-1);
      return;
    }
    var k = profileFor(score), p = PROFILES[k];
    set('qbScore', score + ' of 32');
    set('qbProfile', p.name);
    set('qbProfileText', p.text + ' Score range for this profile: ' + p.min + ' to ' + p.max + '.');
    var g = rollUp(p.mix);
    set('qbStocks', g['Stocks'] + '%');
    set('qbBonds', g['Bonds'] + '%');
    set('qbRealEstate', g['Real estate'] + '%');
    set('qbCashShare', g['Cash and short-term'] + '%');
    CLASSES.forEach(function (name, i) {
      var tr = document.createElement('tr');
      tr.appendChild(cell(name, true));
      tr.appendChild(cell(GROUP[i]));
      tr.appendChild(cell(p.mix[i] + '%'));
      mixBody.appendChild(tr);
    });
    renderCompare(k);
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('qbForm');
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    form.addEventListener('reset', function () { setTimeout(update, 0); });
    update();
  });
})();
